PRAGMA foreign_keys=ON;

CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,username TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS projects(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',start_date TEXT,end_date TEXT,status TEXT NOT NULL DEFAULT 'active',asset TEXT NOT NULL DEFAULT '',contractor TEXT NOT NULL DEFAULT '',po_number TEXT NOT NULL DEFAULT '',estimated_cost REAL NOT NULL DEFAULT 0,actual_cost REAL NOT NULL DEFAULT 0,shutdown_required INTEGER NOT NULL DEFAULT 0,commissioning TEXT NOT NULL DEFAULT 'not_started',closeout TEXT NOT NULL DEFAULT '',notes TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL,project_code TEXT NOT NULL DEFAULT '',forecast_cost REAL NOT NULL DEFAULT 0,contingency REAL NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS tasks(id TEXT PRIMARY KEY,project_id TEXT REFERENCES projects(id) ON DELETE CASCADE,owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,name TEXT NOT NULL,start_date TEXT,due_date TEXT,status TEXT NOT NULL DEFAULT 'todo',priority TEXT NOT NULL DEFAULT 'medium',notes TEXT NOT NULL DEFAULT '',depends_on TEXT,recurring TEXT NOT NULL DEFAULT '',recurring_from TEXT,created_at TEXT NOT NULL,progress INTEGER NOT NULL DEFAULT 0,duration_days INTEGER NOT NULL DEFAULT 1,dependency_type TEXT NOT NULL DEFAULT 'FS');
CREATE TABLE IF NOT EXISTS checklist(id TEXT PRIMARY KEY,task_id TEXT NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,title TEXT NOT NULL,done INTEGER NOT NULL DEFAULT 0,sort_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS milestones(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,title TEXT NOT NULL,due_date TEXT,done INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS attachments(id TEXT PRIMARY KEY,project_id TEXT REFERENCES projects(id) ON DELETE CASCADE,task_id TEXT REFERENCES tasks(id) ON DELETE CASCADE,owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,original_name TEXT NOT NULL,stored_name TEXT NOT NULL,size INTEGER NOT NULL,uploaded_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS activity(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,project_id TEXT REFERENCES projects(id) ON DELETE CASCADE,description TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS phases(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,title TEXT NOT NULL,sort_order INTEGER NOT NULL DEFAULT 0,start_date TEXT,end_date TEXT);
CREATE TABLE IF NOT EXISTS costs(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,title TEXT NOT NULL,vendor TEXT NOT NULL DEFAULT '',po_number TEXT NOT NULL DEFAULT '',amount REAL NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'committed',cost_date TEXT,notes TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS issues(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,title TEXT NOT NULL,kind TEXT NOT NULL DEFAULT 'risk',severity TEXT NOT NULL DEFAULT 'medium',status TEXT NOT NULL DEFAULT 'open',owner_name TEXT NOT NULL DEFAULT '',due_date TEXT,notes TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS baselines(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,created_at TEXT NOT NULL,target_date TEXT,budget REAL NOT NULL DEFAULT 0,snapshot_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS inbox(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,title TEXT NOT NULL,notes TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS notifications(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,project_id TEXT REFERENCES projects(id) ON DELETE CASCADE,message TEXT NOT NULL,kind TEXT NOT NULL DEFAULT 'info',is_read INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS meetings(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,title TEXT NOT NULL,meeting_date TEXT,attendees TEXT NOT NULL DEFAULT '',notes TEXT NOT NULL DEFAULT '',decisions TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS changes(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,title TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',cost_impact REAL NOT NULL DEFAULT 0,schedule_days INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'proposed',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS report_snapshots(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,title TEXT NOT NULL,period_start TEXT,period_end TEXT,snapshot_json TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS saved_views(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,title TEXT NOT NULL,filter_json TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS automation_rules(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,title TEXT NOT NULL,trigger_type TEXT NOT NULL,condition_json TEXT NOT NULL DEFAULT '{}',action_type TEXT NOT NULL,action_json TEXT NOT NULL DEFAULT '{}',enabled INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS report_revisions(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,title TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 0,config_json TEXT NOT NULL DEFAULT '{}',snapshot_json TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS recurring_projects(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,title TEXT NOT NULL,template_project_id TEXT REFERENCES projects(id) ON DELETE SET NULL,frequency TEXT NOT NULL DEFAULT 'monthly',next_date TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS document_revisions(id TEXT PRIMARY KEY,attachment_id TEXT NOT NULL REFERENCES attachments(id) ON DELETE CASCADE,owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,revision INTEGER NOT NULL DEFAULT 1,original_name TEXT NOT NULL,stored_name TEXT NOT NULL,size INTEGER NOT NULL,uploaded_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS decisions(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,decision_no TEXT NOT NULL,title TEXT NOT NULL,decision TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'approved',decided_by TEXT NOT NULL DEFAULT '',decision_date TEXT,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS procurement(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,item TEXT NOT NULL,vendor TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'planning',rfq_date TEXT,po_number TEXT NOT NULL DEFAULT '',delivery_date TEXT,amount REAL NOT NULL DEFAULT 0,notes TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS field_reports(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,report_date TEXT NOT NULL,contractor TEXT NOT NULL DEFAULT '',personnel TEXT NOT NULL DEFAULT '',weather TEXT NOT NULL DEFAULT '',work_completed TEXT NOT NULL DEFAULT '',issues TEXT NOT NULL DEFAULT '',safety TEXT NOT NULL DEFAULT '',next_work TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS project_templates(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,title TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',template_json TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS approvals(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,kind TEXT NOT NULL DEFAULT 'general',title TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'pending',amount REAL NOT NULL DEFAULT 0,schedule_days INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,decided_at TEXT);

CREATE INDEX IF NOT EXISTS idx_tasks_owner_project ON tasks(owner_id,project_id);
CREATE INDEX IF NOT EXISTS idx_tasks_due ON tasks(owner_id,due_date);
CREATE INDEX IF NOT EXISTS idx_projects_owner ON projects(owner_id);
CREATE INDEX IF NOT EXISTS idx_activity_project ON activity(project_id,created_at);
